package kw.urtv.shared;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.net.Uri;import org.json.*;import java.util.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
/** An explicit city search, never a resident location service. */
public class LocationPickerActivity extends TvPage {
 private boolean weatherOnly,cityOnly,en,unselected;private String t(String ar,String english){return en?english:ar;}
 private Place selected;private String country;private final ExecutorService worker=Executors.newSingleThreadExecutor();private Future<?> pending;private volatile HttpURLConnection connection;private int generation;private boolean gone;private EditText input;private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);cityOnly=getIntent().getBooleanExtra("cityOnly",false);weatherOnly=getIntent().getBooleanExtra("weatherOnly",false);en="en".equals(getIntent().getStringExtra("language"));unselected=getIntent().getBooleanExtra("unselected",false);try{selected=Place.parse(b!=null?b.getString("place"):getIntent().getStringExtra("place"));}catch(Exception e){selected=Place.load(this);}country=b==null?getIntent().getStringExtra("country"):b.getString("country",selected.country);if(country==null)country=selected.country;if(!ContentPolicy.country(country))country=selected.country;render();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("place",selected.json());b.putString("country",country);}
 private void cancelSearch(){generation++;if(pending!=null)pending.cancel(true);HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 private void render(){title(weatherOnly?t("مدينة الطقس","Weather city"):cityOnly?t("المدينة أو المنطقة","City or area"):t("مدينة الصلاة","Prayer city"),t("ابحث مرة واحدة · تُحفظ مدينتك فقط","Search once · only your selected city is stored"));list.setLayoutDirection(en?android.view.View.LAYOUT_DIRECTION_LTR:android.view.View.LAYOUT_DIRECTION_RTL);addButton(t("الدولة · ","Country · ")+new Locale("",country).getDisplayCountry(new Locale(en?"en":"ar")),this::countries);
 input=new EditText(this);input.setSingleLine(true);input.setTextColor(palette.ink);input.setHintTextColor(palette.muted);input.setTextSize(20);input.setHint(t("اسم المدينة بالعربية أو الإنجليزية","City name in Arabic or English"));list.addView(input);addButton(t("ابحث عن المدينة","Search city"),this::search);
 if(country.equals("KW"))addButton(t("مناطق الكويت","Kuwait areas"),()->{String[] a=new String[RegionCatalog.ALL.length];for(int i=0;i<a.length;i++)a[i]=RegionCatalog.ALL[i].name;new AlertDialog.Builder(this).setItems(a,(d,i)->{selected=Place.region(i);render();}).show();});
 String[][] quick={{"SA","جدة","21.4858","39.1925","Asia/Riyadh"},{"SA","مكة المكرمة","21.4225","39.8262","Asia/Riyadh"},{"SA","الرياض","24.7136","46.6753","Asia/Riyadh"},{"EG","القاهرة","30.0444","31.2357","Africa/Cairo"},{"GB","لندن","51.5085","-0.1257","Europe/London"},{"US","نيويورك","40.7143","-74.006","America/New_York"}};
 for(String[] a:quick)if(country.equals(a[0]))addButton(a[1],()->{selected=new Place(a[0],a[1],Double.parseDouble(a[2]),Double.parseDouble(a[3]),a[4],Place.methodFor(a[0]),false);render();});
 if(selected.needsConfirmation)note(unselected?t("اختر مدينة من الدولة المحددة.","Choose a city in the selected country."):t("أعد اختيار الدولة والمدينة لاعتماد الموقع.","Confirm your country and city again."));
 status=text(t("المحدد: ","Selected: ")+(selected.needsConfirmation?t("لم تُحدّد","Not selected"):selected.name)+(weatherOnly||cityOnly?"":" · "+selected.label(en)),17,palette.ink);list.addView(status);
 if(!weatherOnly&&!cityOnly){addButton(t("الطريقة التلقائية حسب الدولة","Automatic method for country"),()->{selected=selected.withMethod(Place.methodFor(selected.country),false);render();});
 addButton(t("طريقة الصلاة · ","Prayer method · ")+(selected.manualMethod?t("يدوية · ","Manual · "):t("تلقائية · ","Automatic · "))+selected.label(en),()->new AlertDialog.Builder(this).setItems(en?Place.EN_LABELS:Place.LABELS,(d,i)->{selected=selected.withMethod(Place.METHODS[i],true);render();}).show());
 addButton(t("العصر · ","Asr · ")+(selected.hanafi?t("حنفي","Hanafi"):t("شافعي / مالكي / حنبلي","Shafi / Maliki / Hanbali")),()->{selected=new Place(selected.country,selected.name,selected.lat,selected.lon,selected.zone,selected.method,!selected.hanafi,selected.manualMethod,selected.needsConfirmation);render();});
 note(selected.officialEligible()?t("العجيري عند توفر الجدول؛ حساب الكويت عند تعذر تحديثه.","Al-Ojairi when available; Kuwait calculation otherwise."):t("مواقيت محسوبة بطريقة ","Calculated using ")+selected.label(en)+t("؛ راجع جدول مسجدك عند وجود فرق.","; check your local mosque timetable."));
 if(Math.abs(selected.lat)>48)note(t("العروض العليا: سُبع الليل عند تعذر الزوايا؛ راجع الجهة المحلية.","High latitudes: one-seventh night fallback; check local authority."));
  }addButton(t("اعتماد المدينة","Use city"),()->{if(selected.needsConfirmation||!country.equals(selected.country)){status.setText(t("اختر مدينة من الدولة المحددة أولًا","Choose a city in the selected country first"));return;}setResult(RESULT_OK,new Intent().putExtra("place",selected.json()));finish();});addButton(t("رجوع","Back"),this::finish);note(weatherOnly||cityOnly?"GeoNames / Open-Meteo":"GeoNames / Open-Meteo · Adhan");}
 private void countries(){ArrayList<String> codes=new ArrayList<>(Arrays.asList(Locale.getISOCountries()));codes.removeIf(c->!ContentPolicy.country(c));codes.sort((a,b)->new Locale("",a).getDisplayCountry(new Locale(en?"en":"ar")).compareTo(new Locale("",b).getDisplayCountry(new Locale(en?"en":"ar"))));for(String c:new String[]{"EG","SA","KW"}){codes.remove(c);codes.add(0,c);}String[] labels=new String[codes.size()];for(int i=0;i<labels.length;i++)labels[i]=new Locale("",codes.get(i)).getDisplayCountry(new Locale(en?"en":"ar"));new AlertDialog.Builder(this).setTitle(t("الدولة","Country")).setItems(labels,(d,i)->{cancelSearch();country=codes.get(i);render();}).show();}
 private void search(){String term=input.getText().toString().trim();if(term.length()<2){status.setText(t("اكتب حرفين على الأقل","Enter at least two letters"));return;}cancelSearch();final int token=generation;final String wanted=country;status.setText(t("جارٍ البحث…","Searching…"));pending=worker.submit(()->{try{if(Thread.currentThread().isInterrupted()||token!=generation)return;HttpURLConnection c=(HttpURLConnection)new URL("https://geocoding-api.open-meteo.com/v1/search?count=15&language="+(en?"en":"ar")+"&countryCode="+wanted+"&name="+Uri.encode(term)).openConnection();connection=c;c.setConnectTimeout(7000);c.setReadTimeout(7000);JSONArray results;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[2048];int n;while((n=in.read(bytes))!=-1){out.write(bytes,0,n);if(out.size()>131072)throw new IOException();}results=new JSONObject(out.toString("UTF-8")).optJSONArray("results");}finally{c.disconnect();if(connection==c)connection=null;}
 ArrayList<Place> places=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();if(results!=null)for(int i=0;i<results.length();i++)try{JSONObject j=results.getJSONObject(i);if(!wanted.equals(j.getString("country_code")))continue;Place p=new Place(wanted,j.getString("name"),j.getDouble("latitude"),j.getDouble("longitude"),j.getString("timezone"),Place.methodFor(wanted),false);places.add(p);labels.add(p.name+" · "+(ContentPolicy.text(j.optString("admin1"))?j.optString("admin1",p.zone):p.zone));}catch(Exception ignored){}
 runOnUiThread(()->{if(gone||token!=generation)return;if(places.isEmpty()){status.setText(t("لم نجد المدينة. جرّب اسمها بالإنجليزية.","No results. Try another city name."));return;}status.setText(t("اختر المدينة من النتائج","Choose a city from the results"));new AlertDialog.Builder(this).setTitle(t("نتائج البحث","Search results")).setItems(labels.toArray(new String[0]),(d,i)->{selected=places.get(i);render();}).show();});
 }catch(Exception e){runOnUiThread(()->{if(!gone&&token==generation)status.setText(t("تعذر البحث. تحقق من الإنترنت وحاول مجددًا.","Search unavailable. Check the connection and retry."));});}});}
 @Override protected void onDestroy(){gone=true;cancelSearch();worker.shutdownNow();super.onDestroy();}
}
